contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address receiver, uint amount) public payable {
        // owner == this (we deployed c), so the ownership check passes.
        bool reverted;
        uint balBefore = address(c).balance;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool mustRevert = (receiver == address(0)) || (amount == 0) || (amount > balBefore);
        if (!reverted) {
            // A successful transfer moves exactly `amount` out of c.
            assert(address(c).balance + amount == balBefore);
        } else {
            // On revert the balance is unchanged and the revert was necessary.
            assert(address(c).balance == balBefore && mustRevert);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount, uint selfFund) public payable {
        require(receiver != address(0));
        require(amount > 0);
        require(selfFund == 0 || msg.value >= selfFund);
        if (selfFund > 0 && selfFund <= msg.value) {
            selfFund = selfFund;
        }
        uint totalBefore = address(this).balance + address(c).balance;
        bool reverted;
        try c.sendTo(receiver, amount) { reverted = false; }
        catch { reverted = true; }
        uint totalAfter = address(this).balance + address(c).balance;
        assert(reverted ? (totalAfter == totalBefore)
                        : (totalBefore >= amount && totalAfter == totalBefore - amount));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint funding) public payable {
        require(amount > 0);
        require(funding >= amount);
        require(msg.value >= funding);
        require(address(this).balance - msg.value + msg.value >= funding);
        c = c;
        // fund c with the deployed contract so it can pay out
        // (constructor already ran; send value directly via a top-level call)
        // c has no payable fallback declared, so fund it via selfdestruct-free path:
        // instead we require c to already hold value; use try/catch and assert both branches.
        uint balBefore = address(this).balance;
        bool reverted;
        try c.sendTo(address(this), amount) { reverted = false; }
        catch { reverted = true; }
        uint balAfter = address(this).balance;
        if (reverted) {
            assert(balAfter == balBefore);
        } else {
            assert(address(c).balance >= 0 && balAfter == balBefore + amount);
        }
    }
    receive() external payable {}
}

